/* kernel.c: kmain: bring the machine up, start the shell, become idle. */
#include "common.h"
#include "console.h"
#include "cpu.h"
#include "drivers.h"
#include "memory.h"
#include "task.h"
#include "syscall.h"
#include "multiboot.h"
#include "demos.h"
#include "fs.h"

extern uint8_t kernel_start[], kernel_end[];

/* Table generated by the Makefile (build/userbins.asm): every user program
 * is compiled separately and embedded in the kernel image, then copied into
 * /bin at boot. That's our stand-in for installing software on a disk. */
typedef struct { const char *name; const uint8_t *data; uint32_t size; } user_bin_t;
extern const user_bin_t user_programs[];

static const char motd[] =
    "Welcome to MiniOS!\n"
    "  help      - list commands          programs - user programs in /bin\n"
    "  ls -l /   - browse the file system demo sched - compare schedulers\n"
    "  hello     - run a user-mode program evil     - try to break the kernel\n\n";

static const char readme[] =
    "This file lives on MiniFS, a RAM-disk inode file system.\n"
    "Try: cat, echo hi >> /home/readme.txt, mkdir, cp, mv, rm, stat, df, tree /\n";

static void install_files(void) {
    fs_create("/bin", FT_DIR);
    fs_create("/etc", FT_DIR);
    fs_create("/home", FT_DIR);
    fs_create("/tmp", FT_DIR);
    fs_write_file("/etc/motd", motd, sizeof motd - 1);
    fs_write_file("/home/readme.txt", readme, sizeof readme - 1);
    int n = 0;
    for (const user_bin_t *b = user_programs; b->name; b++, n++) {
        char path[PATH_MAX] = "/bin/";
        strncpy(path + 5, b->name, PATH_MAX - 6);
        if (fs_write_file(path, b->data, b->size) < 0) kprintf("  cannot install %s\n", path);
    }
    kprintf("[ OK ] MiniFS: %d programs installed in /bin\n", n);
}

static void ok(const char *what) {
    console_set_color(C_LGREEN, C_BLACK); kprintf("[ OK ] ");
    console_set_color(C_LGREY, C_BLACK);  kprintf("%s\n", what);
}

void kmain(uint32_t magic, multiboot_info_t *mbi) {
    console_init();
    console_set_color(C_LCYAN, C_BLACK);
    kprintf("MiniOS 1.0: a small x86 teaching kernel\n");
    console_set_color(C_LGREY, C_BLACK);

    if (magic != MULTIBOOT_BOOTLOADER_MAGIC) panic("not loaded by a multiboot loader");
    if (!(mbi->flags & 1)) panic("bootloader gave no memory information");
    kprintf("Kernel at %p-%p (%u KiB), RAM %u MiB\n", (uint32_t)kernel_start,
            (uint32_t)kernel_end, (uint32_t)(kernel_end - kernel_start) / 1024,
            (mbi->mem_upper + 1024) / 1024);

    gdt_init();                                 ok("GDT: kernel + user segments, TSS");
    idt_init();                                 ok("IDT: 32 exception + 16 IRQ + syscall gates");
    pic_init();                                 ok("PIC remapped to vectors 32-47");
    pmm_init(mbi->mem_upper, (uint32_t)kernel_end);
                                                ok("Physical memory manager (bitmap)");
    paging_init();                              ok("Paging enabled");
    heap_init();                                ok("Kernel heap");
    tasking_init();                             ok("Tasking: idle task = pid 0");
    syscall_init();                             ok("System calls on int 0x80");
    timer_init();                               ok("PIT timer at 100 Hz -> preemptive scheduler");
    keyboard_init();                            ok("PS/2 keyboard + serial input");
    fs_init();                                  ok("MiniFS: 1 MiB RAM disk formatted");
    install_files();

    task_create("shell", shell_main, NULL, 7);
    kprintf("\n");

    /* From here on this code is the idle task: the scheduler runs it only
     * when no other task is READY. hlt sleeps the CPU until the next IRQ. */
    __asm__ volatile("sti");
    for (;;) cpu_halt();
}
